import{_ as l,l as o,o as e,c as i,v as t,p as n,x as s,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"SMT","description":"","frontmatter":{"title":"SMT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/smt.md","filePath":"cs/smt.md","lastUpdated":1789023840000}'),A={name:"cs/smt.md"};function h(m,a,S,E,T,_){const r=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="smt" tabindex="-1">SMT <a class="header-anchor" href="#smt" aria-label="Permalink to &quot;SMT&quot;">​</a></h1><div class="epigraph"><p>一条流水线的空档，另一条硬件线程的就绪指令可以填；保留站和 cache 变成共享，单线程 IPC 往往略降。</p><footer>—— 据 Tullsen, Eggers and Levy, Simultaneous Multithreading: Maximizing On-Chip Parallelism, ISCA 1995；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/store-buffer">上一课</a>让访存队列托住未提交写。<a href="/cs/ipc-util">IPC 与利用率</a>写明实测 IPC 常远小于宽度：相关、缺失、误预测造成空槽。本课不重讲绕过。缺口是同时多线程（SMT）：同一核上多个逻辑处理器共享取指/发射/执行，每拍可从两条以上线程各取指令，用别的线程的 ILP 填本线程的停顿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单线程在 load 缺失时，ROB 头堵住，后面即使有独立 ALU 也很快耗尽窗口。再加宽超标量，窗口仍是<strong>同一条依赖链</strong>。缺口不是 SIMD（那是下一课的数据级），而是<strong>再取一条不相关的指令流</strong>：它有自己的 PC、寄存器重命名表、ROB 段或线程 ID 标签。</p><p>Tullsen 等人把同一拍发射来自多线程的指令叫做 SMT，以别于粗粒度切换（一缺失才换线程）。</p><p><span class="marginnote">操作系统看见的是多个 CPU。架构状态（寄存器、控制寄存器、ASID）每线程一份；L1 与执行单元共享。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每线程：PC、寄存器映射、部分 ROB。共享：保留站、ALU、cache、MSHR、store 缓冲（项上打线程号）。发射选择：轮转、或优先未停顿线程。冲刷只杀该线程的投机状态。</p>',9)),(e(),n(p,null,{default:s(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E7%BA%BF%E7%A8%8B%200%20%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20ISS%5B%22%E5%85%B1%E4%BA%AB%E5%8F%91%E5%B0%84%E5%8F%A3%22%5D%0A%20%20T1%5B%22%E7%BA%BF%E7%A8%8B%201%20%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20ISS%0A%20%20ISS%20--%3E%20EX%5B%22%E5%85%B1%E4%BA%AB%E6%89%A7%E8%A1%8C%E5%8D%95%E5%85%83%22%5D%0A%20%20EX%20--%3E%20C0%5B%22%E6%8F%90%E4%BA%A4%E5%88%B0%E5%90%84%E8%87%AA%20ROB%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>存储缓冲查找必须带线程号，否则会把另一线程的 store 转发给自己。TLB 用各自 ASID，上一课已经允许两项共存。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>核级吞吐（两线程 IPC 之和）上升；单线程延迟可能变差，因为带宽被抢。<a href="/cs/cpi-amdahl">阿姆达尔</a>对「只有一条线程」的程序：SMT 几乎不帮，还可能因 cache 污染变慢。适合混合：一条算、一条等内存。</p><p>安全与 QoS：侧信道可以共享 cache 当信道，本栏不展开；操作系统可关 SMT。本课只钉性能机制。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 GPU 的 SIMT 调度，不把超线程商标当正文。多核是「复制整核 + 共享 LLC」，与 SMT「复制架构状态、共享执行」不同轴；后课才走多核。SIMD 用一条指令打一条向量，也不靠第二套 PC。</p><p>后课默认：空档可用另一硬件线程填。规则排列的同构运算，下一课用 SIMD 收指令数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SMT：多套架构状态共享流水线，用别的线程填停顿。</li><li>队列与缓冲必须打线程号；单线程 IPC 可能下降。</li><li>数据级并行（SIMD）是另一轴，下一课。</li><li>出处：Tullsen, Eggers and Levy, <em>ISCA</em>, 1995；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const P=l(A,[["render",h]]);export{B as __pageData,P as default};
